L7_1.m_fWaitTime = 0
L7_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L7_1.m_Talk_KOREA = "오랜만에 손님이로군. 누추하지만 안으로 들게."
L7_1.m_fTalkTime = 0.03
L7_1.m_Talk_JPN = "久々の客人だな。汚いが、どうぞ入ってくれ。"
L7_1.m_Talk_ENG = "It's been a long time since I had a guest. Please, make yourself at home."
