L11_1.m_Talk_SCN = "这是……哪里？"
L11_1.m_Talk_DEU = "Where are we?"
L11_1.m_Talk_FRA = "Where are we?"
L12_1 = {}
L12_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE2@12#Talk"
L12_1.m_CutScenProcessKey = 12
L12_1.m_CutScenID = 6800304
L12_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L12_1.m_bWaitClick = true
L12_1.m_fWaitTime = 0
L12_1.m_Face = "UNIT_LAUGH"
L12_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L12_1.m_Pos = "L"
L12_1.m_Talk_KOREA = "내 오랜 아지트 같은 곳이지. 여기라면 일단 쫓길 일은 없을 거야."
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "私の古いアジトのようなところだ。ここならまず追われることはないだろう。"
L12_1.m_Talk_ENG = "It's my old hideout. No one will be on our tail while we're here."
L12_1.m_Talk_TWN = "這裡是我以前的藏身之處。在這裡暫時不會被追上。"
L12_1.m_Talk_SCN = "这里是我以前的藏身之处。在这里暂时不会被追上。"
L12_1.m_Talk_DEU = "It's my old hideout. No one will be on our tail while we're here."
L12_1.m_Talk_FRA = "It's my old hideout. No one will be on our tail while we're here."
L13_1 = {}
L13_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE2@13#Talk"
L13_1.m_CutScenProcessKey = 13
L13_1.m_CutScenID = 6800304
L13_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L13_1.m_bWaitClick = true
L13_1.m_fWaitTime = 0
L13_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L13_1.m_Pos = "L"
L13_1.m_Talk_KOREA = "마도구를 써서 인식을 저해해 두었어. 보통 사람들에게는 평범한 하숙집으로 보이겠지."
L13_1.m_fTalkTime = 0.03
L13_1.m_Talk_JPN = "魔道具を使って認識を阻害しておいた。普通の人間にはそこらの下宿屋に見えるはずだ。"
L13_1.m_Talk_ENG = "I used a Curio to hinder people's perception. To ordinary people, this place will look like a normal boarding home."
L13_1.m_Talk_TWN = "因為用特殊工具干擾了感知。在普通人看來，這裡只是個普通的寄宿房而已。"
L13_1.m_Talk_SCN = "因为用魔导具干扰了感知。在普通人看来，这里只是个普通的寄宿房罢了。"
L13_1.m_Talk_DEU = "I used a Curio to hinder people's perception. To ordinary people, this place will look like a normal boarding home."
L13_1.m_Talk_FRA = "I used a Curio to hinder people's perception. To ordinary people, this place will look like a normal boarding home."
L14_1 = {}
L14_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE2@14#Talk"
L14_1.m_CutScenProcessKey = 14
L14_1.m_CutScenID = 6800304
L14_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_SERIOUS"
L14_1.m_CharStrID = "SWAN_SWANSONG_NPC_NULL"
L14_1.m_Pos = "R"
L14_1.m_Talk_KOREA = "인식을 저해한다고요? 그만한 마도구를 어디서……?"
L14_1.m_fTalkTime = 0.03
L14_1.m_Talk_JPN = "認識を阻害する？　そんな魔道具をどこで……？"
L14_1.m_Talk_ENG = "Hinder people's perception? Where did you find a Curio that potent...?"
L14_1.m_Talk_TWN = "干擾感知？那樣的特殊工具是從哪裡……？"
L14_1.m_Talk_SCN = "干扰感知？那样的魔导具是从哪里……？"
L14_1.m_Talk_DEU = "Hinder people's perception? Where did you find a Curio that potent...?"
L14_1.m_Talk_FRA = "Hinder people's perception? Where did you find a Curio that potent...?"
L15_1 = {}
L15_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE2@15#Talk"
L15_1.m_CutScenProcessKey = 15
L15_1.m_CutScenID = 6800304
L15_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L15_1.m_bWaitClick = true
L15_1.m_fWaitTime = 0
L15_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L15_1.m_Pos = "L"
L15_1.m_Talk_KOREA = "후후, 자네보다야 덜 하겠지만 나도 제법 인기가 있는 편이거든."
L15_1.m_fTalkTime = 0.03
L15_1.m_Talk_JPN = "ハハ、君ほどではないが私は結構モテるものでね。"
L15_1.m_Talk_ENG = "Haha, it might not be up to your level, but I'm also rather popular."
L15_1.m_Talk_TWN = "呵呵，雖然比不上你，但我也算是相當受歡迎的喔。"
L15_1.m_Talk_SCN = "呵呵，虽然比不上你，但我也算是相当受欢迎的哦。"
L15_1.m_Talk_DEU = "Haha, it might not be up to your level, but I'm also rather popular."
L15_1.m_Talk_FRA = "Haha, it might not be up to your level, but I'm also rather popular."
L16_1 = {}
L16_1.m_CutScenKey_Talk = "SWANSONG_ACT3_INTERLUDE2@16#Talk"
L16_1.m_CutScenProcessKey = 16
L16_1.m_CutScenID = 6800304
L16_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_PRIDE"
L16_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L16_1.m_Pos = "L"
L16_1.m_Talk_KOREA = "물론, 내 목숨을 노리는 범죄자들 한정이지만."
L16_1.m_fTalkTime = 0.03
L16_1.m_Talk_JPN = "もちろん、私の命を狙っている犯罪者限定だが。"
L16_1.m_Talk_ENG = "But only to criminals who want me dead, of course."
L16_1.m_Talk_TWN = "當然，僅限那些想要我命的罪犯。"
