L24_1 = "SWANSONG_ACT3_INTERLUDE2@73#Talk"
L23_1.m_CutScenKey_Talk = L24_1
L24_1 = 73
L23_1.m_CutScenProcessKey = L24_1
L23_1.m_CutScenID = 6800304
L23_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L23_1.m_Pos = "L"
L24_1 = "언뜻 보면, 전혀 상관없는 것들이……. 복잡하게 얽히고 얽혀 어떤 사건을 만들어 내지."
L23_1.m_Talk_KOREA = L24_1
L23_1.m_fTalkTime = 0.03
L24_1 = "最初は何の関係もなく思えても……いつしか複雑に絡み合い、ある出来事を作り出す。"
L23_1.m_Talk_JPN = L24_1
L24_1 = "The things that seem unrelated at first glance... get tangled together to create an event."
L23_1.m_Talk_ENG = L24_1
L24_1 = "乍一看，是完全無關的事物……複雜地交織在一起，才製造出了某種事件。"
L23_1.m_Talk_TWN = L24_1
L24_1 = "乍一看，是完全无关的事物……复杂地交织在一起，才制造出了某种事件。"
L23_1.m_Talk_SCN = L24_1
L24_1 = "The things that seem unrelated at first glance... get tangled together to create an event."
L23_1.m_Talk_DEU = L24_1
L24_1 = "The things that seem unrelated at first glance... get tangled together to create an event."
L23_1.m_Talk_FRA = L24_1
