L26_1 = "아무런 의미 없이 베푼 선행이라 해도, 먼 훗날 그게 어떻게 돌아올지는 아무도 모르지."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "なんの意味もなく施した善行であっても、遠い未来にそれがどのような形で帰ってくるかは誰にもわからない。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Even if my good deeds seem meaningless now, no one knows how it will change the future."
L25_1.m_Talk_ENG = L26_1
L26_1 = "即使是無意間的善行，誰也不知道它將來會以什麼方式回報。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "即使是无意间的善行，谁也不知道它将来会以什么方式回报。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "Even if my good deeds seem meaningless now, no one knows how it will change the future."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Even if my good deeds seem meaningless now, no one knows how it will change the future."
