L33_1 = "PAPERBOY_SWANSONG_NPC_NULL"
L32_1.m_CharStrID = L33_1
L33_1 = "이건, 티켓이잖아? 스완이 나오는 공연 암표는 부르는 게 값이라고 들었는데……?"
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "これはチケット？　スワンが出演する公演のチケットはものすごく高く売れるって聞いたけど……"
L32_1.m_Talk_JPN = L33_1
L33_1 = "It's a ticket. I heard that tickets to Swan's performances can be sold at absurd prices...!"
L32_1.m_Talk_ENG = L33_1
L33_1 = "這……這是門票？聽說有天鵝演出的票可是有價無市的……？"
L32_1.m_Talk_TWN = L33_1
L33_1 = "这……这是演出票？听说有天鹅出演的票可是有价无市的……？"
L32_1.m_Talk_SCN = L33_1
L33_1 = "It's a ticket. I heard that tickets to Swan's performances can be sold at absurd prices...!"
L32_1.m_Talk_DEU = L33_1
L33_1 = "It's a ticket. I heard that tickets to Swan's performances can be sold at absurd prices...!"
L32_1.m_Talk_FRA = L33_1
L33_1 = {}
L34_1 = "SWANSONG_ACT3_INTERLUDE2@83#Talk"
L33_1.m_CutScenKey_Talk = L34_1
L34_1 = 83
L33_1.m_CutScenProcessKey = L34_1
L33_1.m_CutScenID = 6800304
L33_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L34_1 = "PAPERBOY_SWANSONG_NPC_NULL"
L33_1.m_CharStrID = L34_1
L34_1 = "그, 그런데 괜찮아? 나 오페라 같은 건 하나도 몰라."
L33_1.m_Talk_KOREA = L34_1
L33_1.m_fTalkTime = 0.03
L34_1 = "で、でもいいの？　僕、オペラなんて全然わからないよ。"
L33_1.m_Talk_JPN = L34_1
L34_1 = "A-are you sure? I don't know a thing about opera."
L33_1.m_Talk_ENG = L34_1
L34_1 = "那、那個沒關係嗎？我對歌劇一竅不通。"
L33_1.m_Talk_TWN = L34_1
