L43_1 = "동생분께서 저희 공연을 보고 싶다고 하셨다면서요. 그렇다면 오히려 영광이랍니다."
L42_1.m_Talk_KOREA = L43_1
L42_1.m_fTalkTime = 0.03
L43_1 = "妹さんが私たちの公演を見たいって言ったでしょう？　なら、むしろ光栄です。"
L42_1.m_Talk_JPN = L43_1
L43_1 = "You said that your sister wanted to see my show. It would be an honor if you both came to see it."
L42_1.m_Talk_ENG = L43_1
L43_1 = "聽說你妹妹也想看我的演出。那真是我的榮幸。"
