L47_1 = "아무리 뛰어난 해결사라고 해도, 혼자서 모든 것을 해결할 수는 없어."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "いくら立派な解決屋であっても、一人ですべてを解決することはできない。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "No matter how skilled one is as a problem solver, one can't solve everything on one's own."
L46_1.m_Talk_ENG = L47_1
L47_1 = "再優秀的問題解決者，也無法獨自解決所有的難題。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "再优秀的问题解决者，也无法独自解决所有的难题。"
L46_1.m_Talk_SCN = L47_1
L47_1 = "No matter how skilled one is as a problem solver, one can't solve everything on one's own."
L46_1.m_Talk_DEU = L47_1
L47_1 = "No matter how skilled one is as a problem solver, one can't solve everything on one's own."
