L47_1.m_Pos = "C"
L48_1 = "경찰 같은 조직력이 없는, 나 같은 자문 탐정이라면 더욱 그렇지."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "警察のような組織のない、私のような諮問探偵ならなおさらだ。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "That's especially true for a consulting detective like me who has no organizational support, such as the police."
L47_1.m_Talk_ENG = L48_1
L48_1 = "像我這樣的顧問偵探，沒有員警那樣的組織能力，更是如此。"
L47_1.m_Talk_TWN = L48_1
L48_1 = "像我这样的顾问侦探，没有警察那样的组织能力，更是如此。"
L47_1.m_Talk_SCN = L48_1
L48_1 = "That's especially true for a consulting detective like me who has no organizational support, such as the police."
L47_1.m_Talk_DEU = L48_1
L48_1 = "That's especially true for a consulting detective like me who has no organizational support, such as the police."
