L48_1.m_Pos = "C"
L49_1 = "그렇기에 타인을 도와서, 인연을 만들어 두는 거라네."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "だからこそ他人を助け、絆を築いておくのだ。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "That is why I help people and build relationships."
L48_1.m_Talk_ENG = L49_1
L49_1 = "正因為這樣，我才會幫助他人，結下緣分。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "正因为这样，我才会帮助他人，结下缘分。"
L48_1.m_Talk_SCN = L49_1
L49_1 = "That is why I help people and build relationships."
L48_1.m_Talk_DEU = L49_1
L49_1 = "That is why I help people and build relationships."
L48_1.m_Talk_FRA = L49_1
L49_1 = {}
