L49_1.m_Pos = "C"
L50_1 = "과거에 맺었던 인연들은, 틀림없이 미래의 다른 사건을 해결하는데 도움이 될 테니까."
L49_1.m_Talk_KOREA = L50_1
L49_1.m_fTalkTime = 0.03
L50_1 = "過去の絆は、きっと未来の他の事件を解決するのに役立つはずだから。"
L49_1.m_Talk_JPN = L50_1
L50_1 = "The relationships we made in the past will undoubtedly become helpful in solving other cases in the future."
L49_1.m_Talk_ENG = L50_1
L50_1 = "過去結下的緣分，必定會對未來解決其他事件有所幫助。"
L49_1.m_Talk_TWN = L50_1
L50_1 = "过去结下的缘分，必定会对未来解决其他事件有所帮助。"
