L4_1 = "SWANSONG_ACT3_INTERLUDE2@103#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 103
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 6800304
L3_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L3_1.m_Pos = "C"
L4_1 = "결국, 이 세상의 모든 것은 보이지 않는 실로 연결되어 있는 게 아닐까 하고 말이야."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "結局、この世のすべては見えない糸で繋がっているのではないかと。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "In the end, this world is connected by invisible threads, I think."
L3_1.m_Talk_ENG = L4_1
L4_1 = "最終，這個世界上的一切，是不是都被一根看不見的線連接在一起了？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "最终，这个世界上的一切，是不是都被一根看不见的线连接在一起了？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "In the end, this world is connected by invisible threads, I think."
L3_1.m_Talk_DEU = L4_1
L4_1 = "In the end, this world is connected by invisible threads, I think."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "SWANSONG_ACT3_INTERLUDE2@104#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 104
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 6800304
L4_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L4_1.m_Pos = "C"
L5_1 = "그렇다면 역으로 세상을 바꾸기 위해서, 개인이 할 수 있는 건 하나뿐이겠지."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "なら、逆に世界を変えるために、個人ができるのはただ一つしかない。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "So, thinking about it backwards and how to change the world, there's only one thing an individual can do."
L4_1.m_Talk_ENG = L5_1
L5_1 = "那麼，為了改變世界，我個人能做的只有一件事。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "那么，为了改变世界，我个人能做的只有一件事。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "So, thinking about it backwards and how to change the world, there's only one thing an individual can do."
L4_1.m_Talk_DEU = L5_1
L5_1 = "So, thinking about it backwards and how to change the world, there's only one thing an individual can do."
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "SWANSONG_ACT3_INTERLUDE2@105#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 105
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 6800304
L5_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L5_1.m_Pos = "C"
L6_1 = "바로 자신과 연결된 다른 인연을 외면하지 않는 것."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "自分と繋がった絆から目を背けないこと。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "That is to not neglect the relationship one creates with others."
L5_1.m_Talk_ENG = L6_1
L6_1 = "那就是不要回避與自己相連的其他緣分。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "那就是不要回避与自己相连的其他缘分。"
L5_1.m_Talk_SCN = L6_1
L6_1 = "That is to not neglect the relationship one creates with others."
L5_1.m_Talk_DEU = L6_1
L6_1 = "That is to not neglect the relationship one creates with others."
L5_1.m_Talk_FRA = L6_1
L6_1 = {}
L7_1 = "SWANSONG_ACT3_INTERLUDE2@106#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 106
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 6800304
L6_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
