L6_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L6_1.m_Pos = "C"
L7_1 = "그렇게 인연들이 조금씩 쌓이고, 또 쌓인다면……."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "そうやって絆を少しずつ積み重ねていけば……"
L6_1.m_Talk_JPN = L7_1
L7_1 = "And as one builds relationships one after another..."
L6_1.m_Talk_ENG = L7_1
L7_1 = "這樣一來，緣分會一點點積累，再積累……"
L6_1.m_Talk_TWN = L7_1
L7_1 = "这样一来，缘分会一点点积累，再积累……"
L6_1.m_Talk_SCN = L7_1
L7_1 = "And as one builds relationships one after another..."
L6_1.m_Talk_DEU = L7_1
L7_1 = "And as one builds relationships one after another..."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
