L15_1 = "후후, 상관없다니 그거 섭섭한 소리네."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "ふふ、関係ないだなんて悲しいこと言うね。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Haha, you're upsetting me by saying that this has nothing to do with me."
L14_1.m_Talk_ENG = L15_1
L15_1 = "呵呵，你說無所謂，那可真讓人傷心啊。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "呵呵，你说无所谓，那可真让人伤心啊。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Haha, you're upsetting me by saying that this has nothing to do with me."
L14_1.m_Talk_DEU = L15_1
