L16_1 = "나는 네 전속 스태프이고, 너는 우리 극단을 대표하는 프리마돈나인걸?"
L15_1.m_Talk_KOREA = L16_1
L15_1.m_fTalkTime = 0.03
L16_1 = "私はあなたの専属スタッフで、あなたは我が劇団を代表するプリマドンナなのよ？"
L15_1.m_Talk_JPN = L16_1
L16_1 = "I'm your personal staff, and you're the prima donna that represents our theater."
L15_1.m_Talk_ENG = L16_1
L16_1 = "我是你的專屬助理，而你是我們劇團的首席女主角喔？"
