L15_1.m_Talk_SCN = L16_1
L16_1 = "I'm your personal staff, and you're the prima donna that represents our theater."
L15_1.m_Talk_DEU = L16_1
L16_1 = "I'm your personal staff, and you're the prima donna that represents our theater."
