L18_1[L19_1] = true
L18_1.m_Pos = "L"
L19_1 = "왜냐하면 무대 위에서 너는 정말로 아름답게 빛났으니까."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "だって、舞台の上のあなたは本当に美しく輝いていたから。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Because you were always shining so brilliantly up on stage."
L18_1.m_Talk_ENG = L19_1
L19_1 = "因為在舞台上的你，真的非常閃耀、非常美麗。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "因为在舞台上的你，真的非常闪耀、非常美丽。"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Because you were always shining so brilliantly up on stage."
L18_1.m_Talk_DEU = L19_1
L19_1 = "Because you were always shining so brilliantly up on stage."
