L36_1.m_fTalkTime = 0.03
L37_1 = "私の情報によれば、深夜の殺人鬼の四番目の現場を目撃したのは君らしいじゃないか。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "According to my information, you are the one who saw the Midnight Killers' fourth murder scene."
