L45_1.m_Pos = "L"
L46_1 = "지난 증언과 일치하군. 하지만 그 검은 갑옷은 심야의 살인마가 아닐 걸세."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "今までの証言と一致している。だが、その黒い鎧は深夜の殺人鬼ではないだろう。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "It matches with the previous testimony. But that black armor is not the Midnight Killer."
L45_1.m_Talk_ENG = L46_1
L46_1 = "和之前的證詞一致。不過，那黑色盔甲應該不是午夜殺人魔的吧。"
L45_1.m_Talk_TWN = L46_1
L46_1 = "和之前的证词一致。不过，那个黑色盔甲应该不是午夜杀人魔吧。"
L45_1.m_Talk_SCN = L46_1
L46_1 = "It matches with the previous testimony. But that black armor is not the Midnight Killer."
L45_1.m_Talk_DEU = L46_1
