L48_1 = "그건 틀림없은 마물이었어요. 심야의 살인마의 정체는 인간이 아니었다고요."
L47_1.m_Talk_KOREA = L48_1
L47_1.m_fTalkTime = 0.03
L48_1 = "あれは間違いなく魔物でした。深夜の殺人鬼の正体は、人間じゃなかったんです。"
L47_1.m_Talk_JPN = L48_1
L48_1 = "It was definitely a monster. The Midnight Killer wasn't human."
L47_1.m_Talk_ENG = L48_1
L48_1 = "那個人絕對是怪物吧？午夜殺人魔的真面目不是人類。"
