L49_1 = "언제나 냉정하게 생각하게, 스완. 그 정체가 인간인지, 마물인지 그런 건 중요하지 않아."
L48_1.m_Talk_KOREA = L49_1
L48_1.m_fTalkTime = 0.03
L49_1 = "常に冷静に考えたまえ、スワン。その正体が人間か魔物か、そんなことが重要なのではない。"
L48_1.m_Talk_JPN = L49_1
L49_1 = "Always think rationally, Swan. It doesn't matter if it is a human or a monster."
L48_1.m_Talk_ENG = L49_1
L49_1 = "保持冷靜思考，史旺。殺人魔的真面目是人類還是怪物並不重要。"
L48_1.m_Talk_TWN = L49_1
L49_1 = "保持冷静思考，斯旺。杀人魔的真面目是人类还是怪物并不重要。"
