L3_1 = "목 위가 통째로 사라진 네 번째 피해자를 제외하면, 지금까지는 날카로운 날붙이에 의해 시체가 훼손되었어."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "首から上が丸ごとなくなった四番目の被害者を除けば、今までは鋭い刃物によって死体の一部が損傷された。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "Excluding the fourth victim who was beheaded, all the other corpses were mutilated with a sharp blade."
L2_1.m_Talk_ENG = L3_1
