L3_1.m_Face = "UNIT_IDLE"
L3_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L3_1.m_Pos = "C"
L4_1 = "자네는 검은 갑옷이 큰 칼을 들고 있었다고 했지?"
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "君は黒い鎧が大きな刃物を持っていたと言ってたな？"
L3_1.m_Talk_JPN = L4_1
L4_1 = "You said that the black armor was carrying a large sword, right?"
L3_1.m_Talk_ENG = L4_1
L4_1 = "你說你看到的那個人拿著一把大劍，對嗎？"
L3_1.m_Talk_TWN = L4_1
L4_1 = "你说你看到的那个人拿着一把大剑，对吗？"
L3_1.m_Talk_SCN = L4_1
L4_1 = "You said that the black armor was carrying a large sword, right?"
L3_1.m_Talk_DEU = L4_1
L4_1 = "You said that the black armor was carrying a large sword, right?"
L3_1.m_Talk_FRA = L4_1
