L5_1 = "SWANSONG_ACT3_INTERLUDE2@154#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 154
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 6800304
L4_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L4_1.m_bWaitClick = true
