L4_1.m_Face = "UNIT_SERIOUS"
L4_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L4_1.m_Pos = "C"
L5_1 = "하지만 그 정도로 큰 칼에 맞으면, 결코 시체가 훼손되는 정도로는 끝나지 않을 거야."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "だが、それほど大きな刃物で斬られたら、死体に傷がつくほどでは済まないだろう。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "But being slashed by a sword of that size will not just mutilate a part of a corpse."
L4_1.m_Talk_ENG = L5_1
L5_1 = "但是，如果被那麼大的刀砍中，屍體絕對不會保留得那麼完整。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "但是，如果被那么大的刀砍中，尸体绝对不会保留得那么完整。"
L4_1.m_Talk_SCN = L5_1
L5_1 = "But being slashed by a sword of that size will not just mutilate a part of a corpse."
L4_1.m_Talk_DEU = L5_1
L5_1 = "But being slashed by a sword of that size will not just mutilate a part of a corpse."
L4_1.m_Talk_FRA = L5_1
