L9_1 = "SWANSONG_ACT3_INTERLUDE2@158#Talk"
L8_1.m_CutScenKey_Talk = L9_1
L9_1 = 158
L8_1.m_CutScenProcessKey = L9_1
L8_1.m_CutScenID = 6800304
L8_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L8_1.m_bWaitClick = true
L8_1.m_fWaitTime = 0
L8_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L8_1.m_Pos = "L"
L9_1 = "또한 전신 갑옷을 입고 있었다면, 증표를 절단해야 하는 세심한 작업은 힘들겠지."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "また全身鎧をまとっていたなら、印を切断するなどの繊細な作業は困難なはず。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "Also, wearing full body armor will make it difficult to precisely cut out the marks."
L8_1.m_Talk_ENG = L9_1
L9_1 = "而且，如果穿著全身盔甲的話，要進行切除標記的細緻工作就會很困難。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "而且，如果穿着全身盔甲的话，要进行切除标记的细致工作就会很困难。"
L8_1.m_Talk_SCN = L9_1
L9_1 = "Also, wearing full body armor will make it difficult to precisely cut out the marks."
L8_1.m_Talk_DEU = L9_1
L9_1 = "Also, wearing full body armor will make it difficult to precisely cut out the marks."
L8_1.m_Talk_FRA = L9_1
L9_1 = {}
L10_1 = "SWANSONG_ACT3_INTERLUDE2@159#Talk"
L9_1.m_CutScenKey_Talk = L10_1
L10_1 = 159
L9_1.m_CutScenProcessKey = L10_1
L9_1.m_CutScenID = 6800304
L9_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L9_1.m_bWaitClick = true
L9_1.m_fWaitTime = 0
L9_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L9_1.m_Pos = "L"
L10_1 = "결국, 검은 갑옷이 심야의 살인마라는 가정은 무리가 있어."
L9_1.m_Talk_KOREA = L10_1
L9_1.m_fTalkTime = 0.03
L10_1 = "結局、黒い鎧が深夜の殺人鬼であるという仮定では無理がある。"
L9_1.m_Talk_JPN = L10_1
L10_1 = "In conclusion, it's unreasonable to assume that the black armor is the Midnight Killer."
L9_1.m_Talk_ENG = L10_1
L10_1 = "總之，假設黑色盔甲是午夜殺人魔，這個推測有些牽強。"
L9_1.m_Talk_TWN = L10_1
L10_1 = "总之，假设黑色盔甲是午夜杀人魔，这个推测有些牵强。"
L9_1.m_Talk_SCN = L10_1
L10_1 = "In conclusion, it's unreasonable to assume that the black armor is the Midnight Killer."
L9_1.m_Talk_DEU = L10_1
L10_1 = "In conclusion, it's unreasonable to assume that the black armor is the Midnight Killer."
L9_1.m_Talk_FRA = L10_1
