L11_1 = "그럼, 현장에 남아있던 메시지들은요? 그건 어떻게 된 건가요?"
L10_1.m_Talk_KOREA = L11_1
L10_1.m_fTalkTime = 0.03
L11_1 = "じゃあ、現場に残っていたメッセージは？　あれはどういうことですか？"
L10_1.m_Talk_JPN = L11_1
L11_1 = "Then, what about the messages left behind at the scenes? What about them?"
L10_1.m_Talk_ENG = L11_1
L11_1 = "那麼，現場留下的那些塗鴉呢？那些是怎麼回事？"
L10_1.m_Talk_TWN = L11_1
L11_1 = "那么，现场留下的那些涂鸦呢？那些是怎么回事？"
L10_1.m_Talk_SCN = L11_1
L11_1 = "Then, what about the messages left behind at the scenes? What about them?"
L10_1.m_Talk_DEU = L11_1
L11_1 = "Then, what about the messages left behind at the scenes? What about them?"
L10_1.m_Talk_FRA = L11_1
