L15_1.m_fTalkTime = 0.03
L16_1 = "現場のメッセージは<color=#ffd34c>三つ目の試練を越えろ。彼女は錆びない錫のようになるだろう。</color>"
L15_1.m_Talk_JPN = L16_1
