L38_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L39_1 = "런던에서 벌어진 사건의 절반, 그리고 밝혀지지 않은 모든 범죄는 그에게 책임이 있지."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "ロンドンで発生した事件の半分、そして明らかになっていないすべての犯罪は彼に責任がある。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "He is responsible for half of the cases that happened in London, and all of the undisclosed cases."
L38_1.m_Talk_ENG = L39_1
L39_1 = "倫敦發生的一半事件，以及所有未被揭露的犯罪，恐怕都要算在他的頭上。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "伦敦发生的一半事件，以及所有未被揭露的犯罪，恐怕都要算在他的头上。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "He is responsible for half of the cases that happened in London, and all of the undisclosed cases."
L38_1.m_Talk_DEU = L39_1
L39_1 = "He is responsible for half of the cases that happened in London, and all of the undisclosed cases."
L38_1.m_Talk_FRA = L39_1
