L39_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L40_1 = "그 자신은 직접 나서지 않으면서, 범죄자에게 필요한 도움과 자문을 주거든."
L39_1.m_Talk_KOREA = L40_1
L39_1.m_fTalkTime = 0.03
L40_1 = "自身は直接表に出ないが、犯罪者に必要な手助けやアドバイスを提供している。"
L39_1.m_Talk_JPN = L40_1
L40_1 = "He doesn't take action himself, and acts as a consultant to criminals."
L39_1.m_Talk_ENG = L40_1
L40_1 = "他本人並不直接出面，卻為犯罪者提供所需的幫助和諮詢。"
L39_1.m_Talk_TWN = L40_1
L40_1 = "他本人并不直接出面，却为犯罪者提供所需的帮助和咨询。"
