L46_1 = "보름 전. 나는 교수를 직접 마주하고 모든 사태의 배후에 그가 있다는 걸 깨달았지."
L45_1.m_Talk_KOREA = L46_1
L45_1.m_fTalkTime = 0.03
L46_1 = "半月前。私は直接教授と対峙しすべての事態の裏に彼がいるということに気付いた。"
L45_1.m_Talk_JPN = L46_1
L46_1 = "Two weeks ago, I met with him and realized that he was behind it all."
L45_1.m_Talk_ENG = L46_1
L46_1 = "半個月前，我親自面對教授，意識到他是這次事件的幕後黑手。"
