L2_1 = "알고 있어요. 그들은 마석을 제조해서 수많은 신도들을 끌어들이고 있었어요."
L1_1.m_Talk_KOREA = L2_1
L1_1.m_fTalkTime = 0.03
L2_1 = "知ってます。彼らは魔石を作って多くの信徒を集めてました。"
L1_1.m_Talk_JPN = L2_1
L2_1 = "I know them. They are gathering hundreds of followers with their Mana Stones manufacturing."
L1_1.m_Talk_ENG = L2_1
L2_1 = "我知道。他們通過製造魔石吸引了大量信徒。"
L1_1.m_Talk_TWN = L2_1
L2_1 = "我知道。他们通过制造魔石吸引了大量信徒。"
L1_1.m_Talk_SCN = L2_1
L2_1 = "I know them. They are gathering hundreds of followers with their Mana Stones manufacturing."
L1_1.m_Talk_DEU = L2_1
L2_1 = "I know them. They are gathering hundreds of followers with their Mana Stones manufacturing."
L1_1.m_Talk_FRA = L2_1
