L2_1.m_Face = "UNIT_IDLE"
L2_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L2_1.m_Pos = "L"
L3_1 = "조사 결과, 그들의 근거지와 세력, 교리와 행동 강령……."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "調査の結果、彼らの本拠地と勢力、教理と行動規範……"
