L18_1 = "전에 말씀하신 <color=#ffd34c>무언가</color>를 이 세계로 불러내는 의식이로군요."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "前に話してた<color=#ffd34c>何か</color>をこの世界に呼び出す儀式のことですね。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "This must be the ritual to summon <color=#ffd34c>something</color> into this world you mentioned before."
L17_1.m_Talk_ENG = L18_1
L18_1 = "是之前提到的把<color=#ffd34c>某種東西</color>召喚到我們世界的儀式嗎？"
L17_1.m_Talk_TWN = L18_1
L18_1 = "是之前提到的把<color=#ffd34c>某种东西</color>召唤到我们世界的仪式吗？"
L17_1.m_Talk_SCN = L18_1
L18_1 = "This must be the ritual to summon <color=#ffd34c>something</color> into this world you mentioned before."
