L19_1 = "후후, 늦었지만 믿어주니 고맙군."
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "はは、遅かれ信じてくれて、ありがとう。"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Haha, I'm grateful to you for trusting me after all."
L18_1.m_Talk_ENG = L19_1
L19_1 = "哈哈，雖然有點晚了，但還是謝謝你的信任。"
L18_1.m_Talk_TWN = L19_1
L19_1 = "哈哈，虽然有点晚了，但还是谢谢你的信任。"
