L19_1.m_Pos = "L"
L20_1 = "그래. 우리는 심야의 살인마보다 한발 앞서 그 타겟을 찾아내서 보호해야만 해."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "ああ。私たちは深夜の殺人鬼より一歩先にそのターゲットを探して保護しなければならないのだ。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "Correct. We must find and protect the Killer's target before he gets to her first."
L19_1.m_Talk_ENG = L20_1
L20_1 = "對，我們必須比午夜殺人魔更早一步找到並保護那個目標。"
L19_1.m_Talk_TWN = L20_1
