L21_1 = "この事件が奇妙な現象、または不可思議なことで片付けるのではなく。"
L20_1.m_Talk_JPN = L21_1
L21_1 = "This case is not some strange or mysterious phenomenon."
L20_1.m_Talk_ENG = L21_1
L21_1 = "這起事件並不是某種靈異事件或者神秘現象。"
