L21_1.m_Pos = "L"
L22_1 = "이성으로 납득할 수 있고, 해결 가능한 <color=#ffd34c>인간의 소행</color>이라는 걸 대중들에게 공표하고 증명하는 거야."
L21_1.m_Talk_KOREA = L22_1
L21_1.m_fTalkTime = 0.03
L22_1 = "理性的に納得がいき、解決できる<color=#ffd34c>人間の所業</color>だということを大衆に公表して証明するのだ。"
L21_1.m_Talk_JPN = L22_1
L22_1 = "It can be solved with reason, and prove to the public that <color=#ffd34c>a human is behind it</color>."
L21_1.m_Talk_ENG = L22_1
L22_1 = "要向大眾公佈並證明這是<color=#ffd34c>人類所為</color>，是可以用理性理解和解決的。"
L21_1.m_Talk_TWN = L22_1
L22_1 = "要向大众公布并证明这是<color=#ffd34c>人类所为</color>，是可以用理性理解和解决的。"
L21_1.m_Talk_SCN = L22_1
L22_1 = "It can be solved with reason, and prove to the public that <color=#ffd34c>a human is behind it</color>."
L21_1.m_Talk_DEU = L22_1
L22_1 = "It can be solved with reason, and prove to the public that <color=#ffd34c>a human is behind it</color>."
L21_1.m_Talk_FRA = L22_1
