L23_1 = "그래야 심야의 살인마라는 부정적 상징으로 결집된 집단 무의식이 구심점을 잃게 되고."
L22_1.m_Talk_KOREA = L23_1
L22_1.m_fTalkTime = 0.03
L23_1 = "そうすれば、深夜の殺人鬼という否定的な象徴で結集した集合的無意識が中心を失い。"
L22_1.m_Talk_JPN = L23_1
L23_1 = "This will make the collective unconsciousness, united by the negative symbol known as the Midnight Killer lose its pivot."
L22_1.m_Talk_ENG = L23_1
L23_1 = "這樣一來，圍繞午夜殺人魔這個負面象徵形成的集體無意識就會失去中心。"
L22_1.m_Talk_TWN = L23_1
L23_1 = "这样一来，围绕午夜杀人魔这个负面象征形成的集体无意识就会失去中心。"
L22_1.m_Talk_SCN = L23_1
L23_1 = "This will make the collective unconsciousness, united by the negative symbol known as the Midnight Killer lose its pivot."
L22_1.m_Talk_DEU = L23_1
L23_1 = "This will make the collective unconsciousness, united by the negative symbol known as the Midnight Killer lose its pivot."
