L30_1.m_fTalkTime = 0.03
L31_1 = "スコットランドヤードが頑張ってくれているが、たぶん間に合わないだろう。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Scotland Yard will do their best, but it will be difficult to get the timing right."
