L31_1.m_Pos = "C"
L32_1 = "이능력자들은 정부를 불신하고 있으니까, 그들의 자발적인 협력을 바라기도 어려워."
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "異能力者は政府を信頼していないから、彼らの自発的な協力を望むこともできない。"
L31_1.m_Talk_JPN = L32_1
L32_1 = "The Supernaturals distrust the government, so expecting any voluntary cooperation will be difficult."
L31_1.m_Talk_ENG = L32_1
L32_1 = "這些超能力者對政府不信任，所以沒法指望他們自願合作。"
L31_1.m_Talk_TWN = L32_1
L32_1 = "这些异能者对政府不信任，所以没法指望他们自愿合作。"
L31_1.m_Talk_SCN = L32_1
L32_1 = "The Supernaturals distrust the government, so expecting any voluntary cooperation will be difficult."
L31_1.m_Talk_DEU = L32_1
L32_1 = "The Supernaturals distrust the government, so expecting any voluntary cooperation will be difficult."
