L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "やはりもっとも早い方法は黄金の暁団に直接潜入し、信徒のリストを手に入れることだ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "The fastest way would be to infiltrate the Golden Dawn and obtain the list of their members."
