L29_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L29_1.m_Pos = "L"
L30_1 = "첩보에 따르면, 그들은 새로운 신도를 받기 전에 어떤 의식에 동참시킨다고 해."
L29_1.m_Talk_KOREA = L30_1
L29_1.m_fTalkTime = 0.03
L30_1 = "諜報によると、彼らは新しい信徒を受け入れる前にとある儀式に参加させるらしい。"
L29_1.m_Talk_JPN = L30_1
L30_1 = "According to intelligence, they make new recruits participate in a ritual before accepting them."
L29_1.m_Talk_ENG = L30_1
L30_1 = "根據情報，他們在接納新信徒之前會進行某種儀式。"
L29_1.m_Talk_TWN = L30_1
L30_1 = "根据情报，他们在接纳新信徒之前会进行某种仪式。"
L29_1.m_Talk_SCN = L30_1
L30_1 = "According to intelligence, they make new recruits participate in a ritual before accepting them."
L29_1.m_Talk_DEU = L30_1
L30_1 = "According to intelligence, they make new recruits participate in a ritual before accepting them."
L29_1.m_Talk_FRA = L30_1
L30_1 = {}
L31_1 = "SWANSONG_ACT3_INTERLUDE2@280#Talk"
L30_1.m_CutScenKey_Talk = L31_1
L31_1 = 280
L30_1.m_CutScenProcessKey = L31_1
L30_1.m_CutScenID = 6800304
L30_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L30_1.m_bWaitClick = true
L30_1.m_fWaitTime = 0
L30_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L30_1.m_Pos = "L"
L31_1 = "우리 계획은 그 순간을 노려, 그들을 검거하고 신도 명단을 손에 넣는 거지."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "私たちの計画はその瞬間を狙い、彼らを検挙して信徒のリストを手に入れることだ。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Our plan is to wait for that moment, arrest them, and get our hands on the list."
L30_1.m_Talk_ENG = L31_1
L31_1 = "我們的計畫是抓住那個時機，逮捕他們並獲取信徒名單。"
L30_1.m_Talk_TWN = L31_1
L31_1 = "我们的计划是抓住那个时机，逮捕他们并获取信徒名单。"
L30_1.m_Talk_SCN = L31_1
L31_1 = "Our plan is to wait for that moment, arrest them, and get our hands on the list."
L30_1.m_Talk_DEU = L31_1
L31_1 = "Our plan is to wait for that moment, arrest them, and get our hands on the list."
L30_1.m_Talk_FRA = L31_1
L31_1 = {}
L32_1 = "SWANSONG_ACT3_INTERLUDE2@281#Talk"
L31_1.m_CutScenKey_Talk = L32_1
L32_1 = 281
L31_1.m_CutScenProcessKey = L32_1
L31_1.m_CutScenID = 6800304
L31_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L31_1.m_bWaitClick = true
L31_1.m_fWaitTime = 0
L31_1.m_Face = "UNIT_SURPRISE"
L31_1.m_CharStrID = "SWAN_SWANSONG_NPC_NULL"
L31_1.m_Pos = "R"
L32_1 = "의식에 동참시킨다고요? 어떤 의식이죠?"
L31_1.m_Talk_KOREA = L32_1
L31_1.m_fTalkTime = 0.03
L32_1 = "儀式に参加させる？　いったいどんな儀式なんですか？"
L31_1.m_Talk_JPN = L32_1
L32_1 = "Participate in a ritual? What kind of ritual is it?"
L31_1.m_Talk_ENG = L32_1
L32_1 = "參與儀式？什麼儀式？"
L31_1.m_Talk_TWN = L32_1
L32_1 = "参与仪式？什么仪式？"
L31_1.m_Talk_SCN = L32_1
L32_1 = "Participate in a ritual? What kind of ritual is it?"
L31_1.m_Talk_DEU = L32_1
L32_1 = "Participate in a ritual? What kind of ritual is it?"
L31_1.m_Talk_FRA = L32_1
L32_1 = {}
L33_1 = "SWANSONG_ACT3_INTERLUDE2@282#Talk"
L32_1.m_CutScenKey_Talk = L33_1
L33_1 = 282
L32_1.m_CutScenProcessKey = L33_1
L32_1.m_CutScenID = 6800304
L32_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
