L32_1.m_Face = "UNIT_IDLE"
L32_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L32_1.m_Pos = "L"
L33_1 = "<color=#ffd34c>마그눔 오푸스</color>. 이른 바, 마석을 만들어내는 공정이라네."
L32_1.m_Talk_KOREA = L33_1
L32_1.m_fTalkTime = 0.03
L33_1 = "<color=#ffd34c>マグヌム・オプス</color>。いわゆる、魔石を作り出す工程だそうだ。"
L32_1.m_Talk_JPN = L33_1
L33_1 = "<color=#ffd34c>Magnum Opus</color>. It is their process of creating Mana Stones, so to speak."
L32_1.m_Talk_ENG = L33_1
L33_1 = "<color=#ffd34c>偉大傑作</color>。所謂的，就是製造魔石的工藝。"
L32_1.m_Talk_TWN = L33_1
L33_1 = "<color=#ffd34c>伟大杰作</color>。所谓的，就是制造魔石的工艺。"
L32_1.m_Talk_SCN = L33_1
L33_1 = "<color=#ffd34c>Magnum Opus</color>. It is their process of creating Mana Stones, so to speak."
L32_1.m_Talk_DEU = L33_1
L33_1 = "<color=#ffd34c>Magnum Opus</color>. It is their process of creating Mana Stones, so to speak."
L32_1.m_Talk_FRA = L33_1
