L35_1 = 284
L34_1.m_CutScenProcessKey = L35_1
L34_1.m_CutScenID = 6800304
L34_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L34_1.m_bWaitClick = true
