L34_1.m_Pos = "R"
L35_1 = "마그눔 오푸스. 마석을 연성하는 연금술. 그 과정은 니그레도, 알베도, 루베도……."
L34_1.m_Talk_KOREA = L35_1
L34_1.m_fTalkTime = 0.03
L35_1 = "マグヌム・オプス。魔石を錬成する錬金術。その過程はニグレド、アルベド、ルベド……"
L34_1.m_Talk_JPN = L35_1
L35_1 = "Magnum Opus. The alchemy of transmuting Mana Stones. The process is Nigredo, Albedo, and Rubedo..."
L34_1.m_Talk_ENG = L35_1
L35_1 = "偉大傑作。煉成魔石的煉金術。其過程為黑化、白化、紅化……"
L34_1.m_Talk_TWN = L35_1
L35_1 = "伟大杰作。炼成魔石的炼金术。其过程为黑化、白化、红化……"
L34_1.m_Talk_SCN = L35_1
L35_1 = "Magnum Opus. The alchemy of transmuting Mana Stones. The process is Nigredo, Albedo, and Rubedo..."
L34_1.m_Talk_DEU = L35_1
L35_1 = "Magnum Opus. The alchemy of transmuting Mana Stones. The process is Nigredo, Albedo, and Rubedo..."
L34_1.m_Talk_FRA = L35_1
