L36_1.m_Pos = "L"
L37_1 = "마그눔 오푸스는 최후의 <color=#ffd34c>걸작</color>이라는 의미라네."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "マグヌム・オプスは最後の<color=#ffd34c>傑作</color>という意味だ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Magnum Opus means the last <color=#ffd34c>great work</color>."
L36_1.m_Talk_ENG = L37_1
L37_1 = "這個詞的意思是最終的<color=#ffd34c>傑作</color>。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "这个词的意思即是最终的<color=#ffd34c>瑰宝</color>。"
L36_1.m_Talk_SCN = L37_1
L37_1 = "Magnum Opus means the last <color=#ffd34c>great work</color>."
