L37_1.m_Pos = "L"
L38_1 = "연금술에서는 황금을 제조하는 모든 공정을 뜻하기도 하고."
L37_1.m_Talk_KOREA = L38_1
L37_1.m_fTalkTime = 0.03
L38_1 = "錬金術では黄金を作り出す、すべての工程のことを指す。"
L37_1.m_Talk_JPN = L38_1
L38_1 = "In alchemy, it used to mean the entire process of transmuting metal into gold."
L37_1.m_Talk_ENG = L38_1
L38_1 = "在煉金術中，它也指製造黃金的整個過程。"
L37_1.m_Talk_TWN = L38_1
L38_1 = "在炼金术中，它也指制造黄金的整个过程。"
L37_1.m_Talk_SCN = L38_1
L38_1 = "In alchemy, it used to mean the entire process of transmuting metal into gold."
L37_1.m_Talk_DEU = L38_1
L38_1 = "In alchemy, it used to mean the entire process of transmuting metal into gold."
L37_1.m_Talk_FRA = L38_1
L38_1 = {}
