L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 288
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 6800304
L38_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L38_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L38_1.m_Pos = "L"
L39_1 = "한편으로는 인간의 영혼을 불멸의 존재로 바꾸는 기술을 뜻하기도 해."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "一方、人間の魂を不滅の存在に変える技術を指したりもする。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "On the other hand, it also refers to the technology of turning a human's soul into an immortal being."
L38_1.m_Talk_ENG = L39_1
L39_1 = "另一方面，也意指將人類的靈魂轉變為不朽存在的技術。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "另一方面，也意指将人类的灵魂转变为不朽存在的技术。"
L38_1.m_Talk_SCN = L39_1
L39_1 = "On the other hand, it also refers to the technology of turning a human's soul into an immortal being."
L38_1.m_Talk_DEU = L39_1
L39_1 = "On the other hand, it also refers to the technology of turning a human's soul into an immortal being."
L38_1.m_Talk_FRA = L39_1
