L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "무슨 벌을 받고 있는 건가요? 초췌한 걸 보면 며칠은 굶은 것 같은데……."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "何かの罰ですか？　数日は何も食べてないような痩せ姿なんですけど……"
L6_1.m_Talk_JPN = L7_1
L7_1 = "What's going on here? They look haggard as if they haven't eaten for a while..."
L6_1.m_Talk_ENG = L7_1
L7_1 = "他們在受什麼懲罰嗎？看起來很憔悴，像是餓了好幾天……"
L6_1.m_Talk_TWN = L7_1
L7_1 = "他们在受什么惩罚吗？看起来很憔悴，像是饿了好几天……"
