L9_1 = "무가치한 존재를 유의미한 존재로 탈바꿈하는 첫번째 공정이니까요."
L8_1.m_Talk_KOREA = L9_1
L8_1.m_fTalkTime = 0.03
L9_1 = "無価値な存在を意味のある存在に生まれ変わらせる最初の工程なんです。"
L8_1.m_Talk_JPN = L9_1
L9_1 = "It is the first process to undergo a transformation from unworthiness to meaningfulness."
L8_1.m_Talk_ENG = L9_1
L9_1 = "這是將無價值的存在轉變為有意義存在的第一道工序。"
L8_1.m_Talk_TWN = L9_1
L9_1 = "这是将无价值的存在转变为有意义存在的第一道工序。"
