L14_1 = 313
L13_1.m_CutScenProcessKey = L14_1
L13_1.m_CutScenID = 6800304
L13_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L13_1.m_bWaitClick = true
