L13_1.m_Face = "UNIT_HATE"
L13_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L13_1.m_Pos = "C"
L14_1 = "먼저, 그들은 런던 빈민가에서 사람을 납치하여 사원 어딘가에 감금하지."
L13_1.m_Talk_KOREA = L14_1
L13_1.m_fTalkTime = 0.03
L14_1 = "まず、彼らはロンドンのスラム街で人をさらい、寺院のどこかに監禁する。"
L13_1.m_Talk_JPN = L14_1
L14_1 = "First, they kidnap people from the London slums and imprison them somewhere in the temple."
L13_1.m_Talk_ENG = L14_1
L14_1 = "首先，他們會在倫敦的貧民區實行綁架，然後把擄來的貧民關押在修道院的某個地方。"
L13_1.m_Talk_TWN = L14_1
L14_1 = "首先，他们会在伦敦的贫民区实行绑架，然后把掳来的贫民关押在修道院的某个地方。"
L13_1.m_Talk_SCN = L14_1
L14_1 = "First, they kidnap people from the London slums and imprison them somewhere in the temple."
L13_1.m_Talk_DEU = L14_1
L14_1 = "First, they kidnap people from the London slums and imprison them somewhere in the temple."
L13_1.m_Talk_FRA = L14_1
