L15_1 = "SWANSONG_ACT3_INTERLUDE2@314#Talk"
L14_1.m_CutScenKey_Talk = L15_1
L15_1 = 314
L14_1.m_CutScenProcessKey = L15_1
L14_1.m_CutScenID = 6800304
L14_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L14_1.m_bWaitClick = true
L14_1.m_fWaitTime = 0
L14_1.m_Face = "UNIT_SERIOUS"
L14_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L14_1.m_Pos = "C"
L15_1 = "자네 말대로, 이 도시에서 빈민 몇 명쯤 실종된다고 해도 크게 문제되지는 않을 테니까."
L14_1.m_Talk_KOREA = L15_1
L14_1.m_fTalkTime = 0.03
L15_1 = "君が言ったとおり、この都市で貧民が何人か失踪したって大して問題にならないはずだからな。"
L14_1.m_Talk_JPN = L15_1
L15_1 = "Like you said, it isn't a big problem for the city if a few people from the slums go missing."
L14_1.m_Talk_ENG = L15_1
L15_1 = "正如你所說，在這座城市裡，即使有幾個貧民失蹤了，也不會引起太大的問題。"
L14_1.m_Talk_TWN = L15_1
L15_1 = "正如你所说，在这座城市里，即使有几个贫民失踪了，也不会引起太大的问题。"
L14_1.m_Talk_SCN = L15_1
L15_1 = "Like you said, it isn't a big problem for the city if a few people from the slums go missing."
L14_1.m_Talk_DEU = L15_1
L15_1 = "Like you said, it isn't a big problem for the city if a few people from the slums go missing."
L14_1.m_Talk_FRA = L15_1
