L17_1 = "SWANSONG_ACT3_INTERLUDE2@316#Talk"
L16_1.m_CutScenKey_Talk = L17_1
L17_1 = 316
L16_1.m_CutScenProcessKey = L17_1
L16_1.m_CutScenID = 6800304
L16_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L16_1.m_bWaitClick = true
L16_1.m_fWaitTime = 0
L16_1.m_Face = "UNIT_SERIOUS"
L16_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L16_1.m_Pos = "C"
L17_1 = "황금 새벽회의 사원은 런던에서 가장 안개가 짙게 깔리는 강변에 있지."
L16_1.m_Talk_KOREA = L17_1
L16_1.m_fTalkTime = 0.03
L17_1 = "黄金の暁団の寺院は、ロンドンでもっとも霧が濃い川辺にある。"
L16_1.m_Talk_JPN = L17_1
L17_1 = "The Golden Dawn's temple is located near the river where the fog is thickest in all of London."
L16_1.m_Talk_ENG = L17_1
L17_1 = "黃金黎明會的據點位於倫敦濃霧最深的河邊。"
L16_1.m_Talk_TWN = L17_1
L17_1 = "黄金黎明会的据点位于伦敦浓雾最深的河边。"
L16_1.m_Talk_SCN = L17_1
L17_1 = "The Golden Dawn's temple is located near the river where the fog is thickest in all of London."
L16_1.m_Talk_DEU = L17_1
L17_1 = "The Golden Dawn's temple is located near the river where the fog is thickest in all of London."
L16_1.m_Talk_FRA = L17_1
