L18_1 = "SWANSONG_ACT3_INTERLUDE2@317#Talk"
L17_1.m_CutScenKey_Talk = L18_1
L18_1 = 317
L17_1.m_CutScenProcessKey = L18_1
L17_1.m_CutScenID = 6800304
L17_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L17_1.m_bWaitClick = true
L17_1.m_fWaitTime = 0
L17_1.m_Face = "UNIT_HATE"
L17_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L17_1.m_Pos = "C"
L18_1 = "그들은 납치한 빈민들을 안개에 노출시킨 채, 자지도, 먹지도 못하게 한다네."
L17_1.m_Talk_KOREA = L18_1
L17_1.m_fTalkTime = 0.03
L18_1 = "彼らは拉致した貧民たちを霧に晒して、寝ることも、食べることも禁ずる。"
L17_1.m_Talk_JPN = L18_1
L18_1 = "They expose the kidnapped people to the fog and do not allow them to eat or sleep."
L17_1.m_Talk_ENG = L18_1
L18_1 = "他們將綁架來的貧民暴露在霧中，不讓他們睡覺，也不給他們吃的。"
L17_1.m_Talk_TWN = L18_1
L18_1 = "他们将绑架来的贫民暴露在雾中，不让他们睡觉，也不给他们吃的。"
L17_1.m_Talk_SCN = L18_1
L18_1 = "They expose the kidnapped people to the fog and do not allow them to eat or sleep."
L17_1.m_Talk_DEU = L18_1
L18_1 = "They expose the kidnapped people to the fog and do not allow them to eat or sleep."
L17_1.m_Talk_FRA = L18_1
L18_1 = {}
L19_1 = "SWANSONG_ACT3_INTERLUDE2@318#Talk"
L18_1.m_CutScenKey_Talk = L19_1
L19_1 = 318
L18_1.m_CutScenProcessKey = L19_1
L18_1.m_CutScenID = 6800304
L18_1.m_CutScenStrID = "SWANSONG_ACT3_INTERLUDE2"
L18_1.m_bWaitClick = true
L18_1.m_fWaitTime = 0
L18_1.m_Face = "UNIT_SERIOUS"
L18_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L18_1.m_Pos = "C"
L19_1 = "그렇게 극한 상황에 놓인 인간이 장시간 안개에 노출되면 어떻게 변하는 줄 아나?"
L18_1.m_Talk_KOREA = L19_1
L18_1.m_fTalkTime = 0.03
L19_1 = "そんな極限の状況に置かれた人間が長時間霧に晒されるとどうなるか、知っているか？"
L18_1.m_Talk_JPN = L19_1
L19_1 = "Do you know what happens to people who have been exposed to the fog for too long in such an extreme situation?"
L18_1.m_Talk_ENG = L19_1
L19_1 = "你知道長時間暴露在霧中的人在極端情況下會變成什麼樣子嗎？"
L18_1.m_Talk_TWN = L19_1
L19_1 = "你知道长时间暴露在雾中的人在极端情况下会变成什么样子吗？"
L18_1.m_Talk_SCN = L19_1
L19_1 = "Do you know what happens to people who have been exposed to the fog for too long in such an extreme situation?"
L18_1.m_Talk_DEU = L19_1
L19_1 = "Do you know what happens to people who have been exposed to the fog for too long in such an extreme situation?"
L18_1.m_Talk_FRA = L19_1
L19_1 = {}
