L20_1 = "침식병으로 신체가 시커멓게 변하고, 끝내 마물이 된다네."
L19_1.m_Talk_KOREA = L20_1
L19_1.m_fTalkTime = 0.03
L20_1 = "侵食病で体が真っ黒になり、結局は魔物になる。"
L19_1.m_Talk_JPN = L20_1
L20_1 = "The Corruption Syndrome turns their bodies black, and eventually become monsters."
L19_1.m_Talk_ENG = L20_1
L20_1 = "被侵蝕病感染後，身體會變得漆黑，最終變成怪物。"
L19_1.m_Talk_TWN = L20_1
L20_1 = "被侵蚀病感染后，身体会变得漆黑，最终变成魔物。"
L19_1.m_Talk_SCN = L20_1
L20_1 = "The Corruption Syndrome turns their bodies black, and eventually become monsters."
L19_1.m_Talk_DEU = L20_1
