L24_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L24_1.m_Pos = "L"
L25_1 = "그래, 그들은 그걸 <color=#ffd34c>니그레도</color>. 흑화 과정이라고 불러."
L24_1.m_Talk_KOREA = L25_1
L24_1.m_fTalkTime = 0.03
L25_1 = "そう、彼らはこれを<color=#ffd34c>ニグレド</color>。黒化過程と呼んでいる。"
L24_1.m_Talk_JPN = L25_1
L25_1 = "Yes. To them, this is <color=#ffd34c>Nigredo</color>. The process of blackening."
L24_1.m_Talk_ENG = L25_1
L25_1 = "是的，他們稱之為<color=#ffd34c>尼格列多</color>，也就是黑化過程……"
L24_1.m_Talk_TWN = L25_1
L25_1 = "是的，他们称之为<color=#ffd34c>尼格列多</color>，也就是黑化过程……"
L24_1.m_Talk_SCN = L25_1
L25_1 = "Yes. To them, this is <color=#ffd34c>Nigredo</color>. The process of blackening."
L24_1.m_Talk_DEU = L25_1
L25_1 = "Yes. To them, this is <color=#ffd34c>Nigredo</color>. The process of blackening."
