L25_1.m_CharStrID = "ABBERLINE_SWANSONG_NPC_NULL"
L25_1.m_Pos = "L"
L26_1 = "다시 말해, 인간을 마물로 바꾸고 다시 그 마물로부터 마석을 채취하고 있는 거야."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "つまり、人間を魔物に変えて、またその魔物から魔石を採取しているのだ。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "In other words, they turn humans into monsters and harvest Mana Stones from them."
L25_1.m_Talk_ENG = L26_1
L26_1 = "實質上就是將人類變成怪物，然後從這些怪物身上採集魔石的第一步。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "实质上就是将人类变成魔物，然后从这些魔物身上采集魔石的第一步。"
L25_1.m_Talk_SCN = L26_1
L26_1 = "In other words, they turn humans into monsters and harvest Mana Stones from them."
L25_1.m_Talk_DEU = L26_1
L26_1 = "In other words, they turn humans into monsters and harvest Mana Stones from them."
L25_1.m_Talk_FRA = L26_1
