L44_1 = "이능력자도 아닌, 평범한 인간이 안개 좀 쐬었다고 마물이 된다고요?"
L43_1.m_Talk_KOREA = L44_1
L43_1.m_fTalkTime = 0.03
L44_1 = "異能力者でもない、普通の人間が霧にちょっと露出されただけで魔物になるんですか？"
L43_1.m_Talk_JPN = L44_1
L44_1 = "Even ordinary humans who are not Supernaturals become monsters when exposed to the fog?"
