L47_1 = "마물이 되는 게 이능력자뿐이라는 인식은 런던 그림자 사태로 인한 오해야."
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "魔物になるのが異能力者だけだとういう認識は、ロンドンのシャドウ事変から生じた誤解だ。"
L46_1.m_Talk_JPN = L47_1
L47_1 = "The misconception that only Supernaturals become monsters is a misunderstanding due to London's Shadow incident."
L46_1.m_Talk_ENG = L47_1
L47_1 = "認為只有超能力者會變成怪物的看法，是倫敦陰影事件引起的誤會。"
L46_1.m_Talk_TWN = L47_1
L47_1 = "认为只有异能者会变成魔物的看法，是伦敦阴影事件引起的误会。"
