L5_1 = "지금은 인체에 유해한 수준이지만, 안개가 더 짙어지면 곳곳에서 문제가 터질 거야."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "今のところは人体に有害な程度で済むんだが、これ以上霧が濃くなると各地で問題が相次ぐだろう。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "Even now, the fog is harmful to humans. But if it gets any thicker, it will cause more problems."
L4_1.m_Talk_ENG = L5_1
