L5_1[L6_1] = L7_1
L6_1 = "런던의 시민들이 왜 별것도 아닌 이유로, 서로를 증오하게 되었는지 생각해 본 적 있나?"
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "ロンドンの市民がどうして些細な理由でお互い憎むようになったか、考えてみたことはあるか？"
L5_1.m_Talk_JPN = L6_1
L6_1 = "Have you ever thought why the people of London started hating each other for seemingly trivial reasons?"
L5_1.m_Talk_ENG = L6_1
L6_1 = "你有沒有想過，倫敦的市民為什麼會因為一些無關緊要的理由而互相憎恨？"
L5_1.m_Talk_TWN = L6_1
L6_1 = "你有没有想过，伦敦的市民为什么会因为一些无关紧要的理由而互相憎恨？"
