L7_1 = "평범한 인간이든, 이능력자든 하물며 나나 자네도 예외는 없어."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "普通の人間でも異能力者でも、なんなら私も君も、例外ではない。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "Ordinary humans and Supernaturals alike, even you and I are not the exception."
