L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "자네의 연기는 훌륭했지만, 런던에서 발생하는 모든 정보는 내 손아귀 안에 있다네."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "君の演技は素晴らしかったが、ロンドンで発生しているすべての情報は私の手の内にあるのだ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I applaud your acting, but all the information about what happens in London is in the palm of my hand."
L6_1.m_Talk_ENG = L7_1
L7_1 = "你的演技很出色，但倫敦發生的所有資訊都在我的掌握之中。"
L6_1.m_Talk_TWN = L7_1
